def is_valid_palindrome(s: str) -> bool:
    """
    Checks if the input string is a valid palindrome, ignoring spaces and case.
    """
    i, j = 0, len(s) - 1
    while i < j:
        while i < j and not s[i].isalnum():
            i += 1
        while i < j and not s[j].isalnum():
            j -= 1
        if s[i].lower() != s[j].lower():
            return False
        i, j = i + 1, j - 1
    return True
